import 'dotenv/config';
import { NestFactory } from '@nestjs/core';
import { AppModule } from '../../../src/app.module';
import { PrismaService } from '../../../src/prisma/prisma.service';
import { PublisherReportService } from 'src/modules/publisher-report/publisher-report.service';

async function bootstrap() {
  console.log('🌱 Ejecutando seed...');

  const app = await NestFactory.createApplicationContext(AppModule);

  const prisma = app.get(PrismaService);
  const publisherReportService = app.get(PublisherReportService);

  const congregation = await prisma.congregation.findFirst({
    where: { name: 'Norte De Malambo' },
  });

  if (!congregation) {
    console.log('Error: La congregación "Norte De Malambo" no existe.');
    return;
  }

  const MONTHS = {
    Enero: 1,
    // Febrero: 2,
    // Marzo: 3,
    // Abril: 4,
    // Mayo: 5,
    // Junio: 6,
    // Julio: 7,
    // Agosto: 8,
    Septiembre: 9,
    Octubre: 10,
    Noviembre: 11,
    Diciembre: 12,
  };

  for (const report of reports) {
    if (!MONTHS[report.month]) continue;

    const person = await prisma.person.findFirst({
      where: {
        first_name: {
          equals: report.nombre,
          mode: 'insensitive',
        },
        last_name: {
          equals: report.apellido,
          mode: 'insensitive',
        },
      },
      select: {
        id: true,
      },
    });

    if (!person) {
      console.log(`Error: No se encontró perosona con el nombre ${report.nombre} ${report.apellido}`);
      continue;
    }

    delete report.nombre;
    delete report.apellido;

    report.person_id = person.id;
    report.service_year = Number(report.service_year);
    report.year = Number(report.year);
    report.month = MONTHS[report.month];
    if (report.hours && !isNaN(report.hours)) report.hours = Number(report.hours);
    else delete report.hours;

    if (report.bible_courses && !isNaN(report.bible_courses)) report.bible_courses = Number(report.bible_courses);
    else delete report.bible_courses;

    try {
      await publisherReportService.create(report);
    } catch (error) {
      console.error(error);
    }
  }

  console.log('✅ Seed completado correctamente');

  await app.close();
}

bootstrap().catch((error) => {
  console.error('❌ Error ejecutando seed:', error);
  process.exit(1);
});

